(function loadSprites(){
  const names=Object.keys(SPRITE_SRC), total=names.length;
  const done=()=>{ _spriteLoads++;
    // rita om så snart en bild kommit in (progressiv ifyllning), och när alla är klara
    if(roomView==="sprite"&&typeof drawRoom==="function"){ try{drawRoom();}catch(e){} }
    if(_spriteLoads>=total)spritesReady=true;
  };
  names.forEach(n=>{ const img=new Image();
    img.onload=done; img.onerror=done;
    img.src=SPRITE_SRC[n]; SPRITES[n]=img; });
})();
// registrera ev. egna sprites + bakgrund som följer med layouten
function registerLayoutAssets(){
  if(typeof ROOM_LAYOUT!=="object")return;
  if(ROOM_LAYOUT.customSprites){ for(const [n,url] of Object.entries(ROOM_LAYOUT.customSprites)){
    if(!SPRITES[n]||!SPRITES[n].src){ const im=new Image(); im.onload=()=>{try{if(roomView==="sprite")drawRoom();}catch(e){}}; im.src=url; SPRITES[n]=im; SPRITE_SRC[n]=url; } } }
  if(ROOM_LAYOUT.background){ ROOM_BG_IMG=new Image(); ROOM_BG_IMG.onload=()=>{try{if(roomView==="sprite")drawRoom();}catch(e){}}; ROOM_BG_IMG.src=ROOM_LAYOUT.background; }
  else ROOM_BG_IMG=null;
}
