function patientSprite(){
  if(S.airway==="tub"||S.airway==="koniotomi")return SPRITES.pat_intubated;
  if(S.pads)return SPRITES.pat_pads;
  if(S.access)return SPRITES.pat_iv;
  return SPRITES.pat_unconscious;
}
// rita bild centrerad på (cx,cy) med given höjd, valfri rotation
function blit(g,img,cx,cy,h,rot){
  if(!img||!img.width)return false;
  const sc=h/img.height, w=img.width*sc;
  g.save(); g.translate(cx,cy); if(rot)g.rotate(rot);
  g.drawImage(img,-w/2,-h/2,w,h); g.restore(); return true;
}


function render(dt){
  dbgTick();
  compPhase+=dt*(S.comp?11:0);
  drawRoom();
  drawECG(dt);
  drawArt(dt);
  drawUSPanel(dt);
  updateVitals();
  updateChips();
  renderActions();
  renderTeam();
  if(S.phase==="prearrival"){
    $("clock").firstChild.textContent="00:"+String(Math.ceil(S.arrivalIn)).padStart(2,"0");
    const sm=$("clock").querySelector("small"); if(sm)sm.textContent="Patienten anländer om";
  } else {
    $("clock").firstChild.textContent=mmss(S.t);
    const sm=$("clock").querySelector("small"); if(sm)sm.textContent="Tid sedan hjärtstopp";
  }
}

/* ---------- Ultraljud hjärta (subxifoidal 4-kammarvy) ---------- */
function usStruct(){                 // dominerande bestående patologi (styr själva ritningen)
  // Prioritetsordning tamponad > lungemboli > hypovolemi när flera samtidiga orsaker
  // (hardcore) råkar ha var sitt distinkt strukturellt fynd — canvasen kan bara rita EN
  // bild åt gången, men usText() nedan nämner ALLA fynd i den skrivna beskrivningen.
  if(S.causes.some(c=>c.id==="tamponad")&&!S.treatProgress.perikard)return "tamponad";
  if(hasActiveCause("pe"))return "rv";
  if(hasActiveCause("hypovol"))return "empty";
  return "normal";
}
function usStructsAll(){             // alla samtidigt föreliggande strukturella fynd, för texten
  const out=[];
  if(S.causes.some(c=>c.id==="tamponad")&&!S.treatProgress.perikard)out.push("tamponad");
  if(hasActiveCause("pe"))out.push("rv");
  if(hasActiveCause("hypovol"))out.push("empty");
  return out;
}
function usFunc(){                   // aktuell mekanisk funktion (styrs av rytm nu)
  if(S.rosc)return "good";
  if(S.rhythm==="VF")return "vf";
  if(S.rhythm==="asystoli")return "still";
  if(S.perfusing)return "good";
  return "weak";                     // PEA: elektrisk aktivitet, ingen/svag kontraktion
}
function usText(){
  const structs=usStructsAll(), f=usFunc();
  const TXT={
    tamponad:"Stor cirkumferentiell perikardvätska (ekofri rand) med diastolisk kollaps av höger förmak/kammare, <b>tamponad</b>. Hjärtat 'svänger' i vätskan. ",
    rv:"Kraftigt <b>dilaterad höger kammare</b> (RV ≥ LV) med septumdeviation och D-formad vänsterkammare (tryckbelastning). Förenligt med lungemboli. ",
    empty:"Litet, underfyllt och <b>hyperdynamiskt</b> vänsterkammarlumen ('kissing walls'). Talar för hypovolemi. "
  };
  const a=structs.map(s=>TXT[s]).join("");
  let b={good:"Kraftfull, organiserad väggrörelse, god kontraktilitet.",
    weak:"Elektrisk aktivitet men mycket svag/knappt synlig kontraktion (PEA).",
    vf:"Ingen organiserad rörelse, fint fibrillerande myokard.",
    still:"Helt stillastående myokard (asystoli/standstill)."}[f];
  return a+b;
}
function doCardiacUS(){
  S.usDone=true; S.usActive=true;
  if(!S._spk){                       // statiskt speckle-mönster genereras en gång
    S._spk=[]; for(let i=0;i<150;i++)S._spk.push({a:rnd(-0.62,0.62),r:rnd(30,188),b:rnd(.02,.10),s:rnd(.6,1.7)});
  }
  S.usFindings={mode:usStruct(),txt:usText()};
  $("usPanel").classList.remove("hidden");
}
// mjuk 0..1
function smooth(x){x=clamp(x,0,1);return x*x*(3-2*x);}
function drawUSPanel(dt){
  if(!S.usActive)return;
  const cv=$("us"); if(!cv)return; const g=cv.getContext("2d"),W=300,H=200;
  const now=(typeof performance!=="undefined"?performance.now():Date.now())/1000;
  const struct=usStruct(), func=usFunc();
  g.clearRect(0,0,W,H);

  // ---- ultraljudssektor ----
  const apexX=W/2, apexY=2, half=0.62, R=192;
  g.save();
  g.beginPath();g.moveTo(apexX,apexY);
  g.arc(apexX,apexY,R,Math.PI/2-half,Math.PI/2+half);g.closePath();g.clip();
  g.fillStyle="#060d0b";g.fillRect(0,0,W,H);

  // ---- nära fält: lever (mjuk grå textur upptill) ----
  const lg=g.createLinearGradient(0,10,0,95);
  lg.addColorStop(0,"rgba(120,140,128,0.55)");lg.addColorStop(1,"rgba(30,44,38,0.0)");
  g.fillStyle=lg;g.fillRect(0,8,W,95);
  for(let i=0;i<50;i++){const a=rnd(-half,half),r=rnd(20,90);
    g.fillStyle="rgba(150,170,158,"+rnd(.04,.13)+")";
    g.beginPath();g.arc(apexX+Math.sin(a)*r,apexY+Math.cos(a)*r,rnd(.8,2.2),0,7);g.fill();}
  // speckle-fält
  for(const p of (S._spk||[])){
    const x=apexX+Math.sin(p.a)*p.r, y=apexY+Math.cos(p.a)*p.r;
    g.fillStyle="rgba(150,190,175,"+(p.b*(0.7+0.3*Math.sin(now*3+p.r)))+")";
    g.beginPath();g.arc(x,y,p.s,0,7);g.fill();
  }

  // ---- hjärtcykel ----
  const rate=S.rosc?92:(func==="good"?70:64), period=60/rate;
  const ph=((now%period)+period)%period/period;           // 0..1
  const sysFrac=0.42;
  let c;                                                    // kontraktion 0..1
  if(func==="still")c=0;
  else if(func==="vf")c=0;
  else c=(ph<sysFrac)?smooth(Math.sin(ph/sysFrac*Math.PI)):0;
  if(func==="weak")c*=0.16;
  const diast=(ph>=sysFrac);

  // svängning vid tamponad
  const swing=(struct==="tamponad")?Math.sin(now*2.1)*7:0;

  // ---- rita hjärtat (subkostal 4-kammare, organiska former) ----
  // Kanoniskt plan: apex uppåt (-Y), förmak nedåt (+Y), septum vertikalt (X=0),
  // LV = höger (+X, parabolisk), RV = vänster (-X, triangulär, mindre),
  // LA = höger nere, RA = vänster nere. Roteras sedan till subkostal diagonal.
  const u=23, ang=56*Math.PI/180;             // rotation, finjusterad i vektoreditorn
  const hx=141+swing, hy=115 + (struct==="tamponad"?Math.cos(now*2.1)*3:0);
  g.save();g.translate(hx,hy);g.rotate(ang);

  // strukturberoende parametrar
  let lvScale=1, rvScale=1, septX=-0.004, effusion=(struct==="tamponad");
  if(struct==="empty"){lvScale=0.62;rvScale=0.7;}
  if(struct==="rv"){rvScale=1.7;lvScale=0.82;septX=0.846;}      // stor RV + D-formad LV (baslinje + RV_SEPTUM_BULGE 0.85, se vektoreditorn)
  const lvSq=(struct==="empty")?(1-0.72*c):(1-0.46*c);
  const rvSq=(struct==="rv")?(1-0.12*c):(1-0.40*c);
  const atG=1+0.14*c;
  const raC=(struct==="tamponad"&&diast)?0.83:1;               // diastolisk kollaps
  const rvC=(struct==="tamponad"&&diast)?0.8:1;

  // ---------- path-hjälpare (kanoniska koordinater i u) ----------
  function P(x,y){return [x*u,y*u];}
  // ritar konturen i det AKTUELLA (redan öppna) sökvägsobjektet, utan egen beginPath/closePath.
  function outlinePath(){
    g.moveTo(...P(0.16,-2.55));                                 // LV-apex (hjärtats spets)
    g.bezierCurveTo(...P(1.35,-2.2),...P(2.02,-1.0),...P(1.94,0.05));   // LV fri vägg
    g.bezierCurveTo(...P(1.9,0.5),...P(1.86,0.75),...P(1.7,1.0));       // AV-fåra höger
    g.bezierCurveTo(...P(1.55,1.75),...P(0.95,2.06),...P(0.12,2.0));    // LA vägg → botten
    g.bezierCurveTo(...P(-0.75,2.06),...P(-1.4,1.7),...P(-1.287,1.041));// RA vägg
    g.bezierCurveTo(...P(-1.28,0.41),...P(-1.338,0.501),...P(-1.038,-0.133)); // AV-fåra vänster
    g.bezierCurveTo(...P(-0.797,-1.496),...P(-0.618,-1.594),...P(-0.35,-2.3));// RV fri vägg → mot apex
    g.bezierCurveTo(...P(-0.1,-2.42),...P(0.02,-2.5),...P(0.16,-2.55));
    g.closePath();
  }
  function outline(){ g.beginPath(); outlinePath(); }
  // perikardvätska (tamponad), fritt tecknad kontur runt hjärtat, ritas separat och FÖRE myokardet
  function pericardOutline(){
    g.beginPath();
    g.moveTo(...P(-1.449,-1.881));
    g.bezierCurveTo(...P(-0.645,-2.815),...P(0.032,-3.54),...P(1.663,-1.821));
    g.bezierCurveTo(...P(2.834,0.12),...P(2.165,2.195),...P(-0.087,2.553));
    g.bezierCurveTo(...P(-2.393,1.526),...P(-2.706,0.937),...P(-1.449,-1.881));
    g.closePath();
  }
  function lvCav(){
    // parabolisk/bullet: apex upptill, mitralisannulus nedtill; septX styr D-form vid RV-dilatation
    g.beginPath();
    g.moveTo(...P(0.2,-2.304));
    g.bezierCurveTo(...P(0.937,-2.597),...P(2.138,0.568),...P(1.211,0.329));  // fri vägg ned
    g.lineTo(...P(0.335,0.285));                                             // mitralis medial
    g.quadraticCurveTo(...P(septX,-1.015),...P(0.2,-2.304));                 // septal sida (bow=septX)
    g.closePath();
  }
  function rvCav(){
    g.beginPath();
    g.moveTo(...P(-0.112,-2.151));
    g.bezierCurveTo(...P(-0.413,-2.371),...P(-1.115,0.054),...P(-0.645,0.036)); // fri vägg
    g.lineTo(...P(-0.063,0.074));                                              // trikuspidalis medial
    g.quadraticCurveTo(...P(0.299,0.241),...P(-0.112,-2.151));                 // septal sida (delad med IVS)
    g.closePath();
  }
  function laCav(){
    g.beginPath();
    g.moveTo(...P(0.784,0.651));
    g.bezierCurveTo(...P(1.25,0.35),...P(1.35,1.25),...P(0.7,1.62));
    g.bezierCurveTo(...P(0.4,1.78),...P(0.16,1.5),...P(0.16,0.9));
    g.bezierCurveTo(...P(0.16,0.5),...P(0.52,0.617),...P(0.784,0.651));
    g.closePath();
  }
  function raCav(){
    g.beginPath();
    g.moveTo(...P(-0.6,0.608));
    g.bezierCurveTo(...P(-1.15,0.28),...P(-1.28,1.2),...P(-0.66,1.56));
    g.bezierCurveTo(...P(-0.36,1.72),...P(-0.14,1.45),...P(-0.14,0.85));
    g.bezierCurveTo(...P(-0.14,0.45),...P(-0.291,0.464),...P(-0.6,0.608));
    g.closePath();
  }
  // skala en kavitet mot dess tyngdpunkt (systolisk kontraktion)
  function squeeze(cx,cy,s,draw){g.save();g.translate(cx*u,cy*u);g.scale(s,s);g.translate(-cx*u,-cy*u);draw();g.restore();}

  // ---------- perikardvätska (tamponad), ritas bakom myokardet ----------
  if(effusion){
    g.fillStyle="#111111"; pericardOutline(); g.fill();
    g.strokeStyle="rgba(232,243,236,0.6)"; g.lineWidth=1.5; pericardOutline(); g.stroke();
  }

  // ---------- myokard ----------
  const myoGrad=g.createLinearGradient(0,-2.4*u,0,2*u);
  myoGrad.addColorStop(0,"#cfdbd3");myoGrad.addColorStop(0.5,"#9db0a7");myoGrad.addColorStop(1,"#b4c3ba");
  g.fillStyle=myoGrad; outline(); g.fill();
  // textur i väggen
  g.save(); outline(); g.clip();
  for(let i=0;i<120;i++){const rx=rnd(-1.8,2.0)*u, ry=rnd(-2.6,2.1)*u;
    g.fillStyle=(Math.random()<0.5?"rgba(244,250,246,":"rgba(64,84,76,")+rnd(.05,.20)+")";
    g.beginPath();g.arc(rx,ry,rnd(.5,1.5),0,7);g.fill();}
  g.restore();
  g.strokeStyle="rgba(226,240,232,0.8)";g.lineWidth=1.4; outline(); g.stroke();

  // ---------- kaviteter (ekofritt blod) ----------
  function fillCav(path,shrinkC,cx,cy){
    g.fillStyle="#03100d";
    squeeze(cx,cy,shrinkC,()=>{path();g.fill();});
    g.strokeStyle="rgba(206,226,217,0.55)";g.lineWidth=1;
    squeeze(cx,cy,shrinkC,()=>{path();g.stroke();});
  }
  // LV
  g.save();g.translate(0,0);g.scale(lvScale,lvScale);
    fillCav(lvCav,lvSq,0.75,-0.7);
  g.restore();
  // RV
  g.save();g.scale(rvScale,rvScale);
    fillCav(rvCav,rvSq*rvC,-0.6,-0.6);
  g.restore();
  // förmak
  fillCav(laCav,atG,0.7,1.0);
  fillCav(raCav,atG*raC,-0.6,0.95);

  // ---------- VF: kaotisk quiver ----------
  if(func==="vf"){
    g.save();outline();g.clip();
    g.strokeStyle="rgba(210,228,218,0.45)";g.lineWidth=1;
    for(let i=0;i<12;i++){const yy=(-2.4+i*0.42)*u;
      g.beginPath();g.moveTo(-1.8*u,yy);
      for(let x=-1.8*u;x<2*u;x+=5){g.lineTo(x, yy+Math.sin(now*38+x*0.35+i*1.3)*3);}
      g.stroke();}
    g.restore();
  }

  g.restore(); // hjärtplan

  // djupberoende gain (mörkare på djupet)
  const dg=g.createRadialGradient(apexX,apexY,40,apexX,apexY,R);
  dg.addColorStop(0,"rgba(0,0,0,0)");dg.addColorStop(1,"rgba(0,0,0,0.45)");
  g.fillStyle=dg;g.fillRect(0,0,W,H);
  g.restore(); // sektor-clip

  // ---- sektorram, djupmarkeringar, text ----
  g.strokeStyle="#2a463f";g.lineWidth=1.5;
  g.beginPath();g.moveTo(apexX,apexY);
  g.arc(apexX,apexY,R,Math.PI/2-half,Math.PI/2+half);g.closePath();g.stroke();
  g.strokeStyle="rgba(120,150,140,0.4)";g.lineWidth=1;
  for(let d=0.25;d<1;d+=0.25){g.beginPath();g.arc(apexX,apexY,R*d,Math.PI/2-half,Math.PI/2+half);g.stroke();}
  g.fillStyle="#7fa093";g.font="8px 'IBM Plex Mono'";
  g.fillText("Subxifoidal 4C",8,H-8);
  g.fillText((S.rosc?"ROSC":mmss(S.t)),W-56,H-8);
  // små kammarförkortningar för inlärning
  g.fillStyle="rgba(200,220,210,0.55)";g.font="9px 'IBM Plex Mono'";

  if(S.usFindings){S.usFindings.mode=struct;S.usFindings.txt=usText();
    $("usInfo").innerHTML="<b>Fynd:</b> "+S.usFindings.txt+
      "<br><span class='muted'>Realtidsbild, kontraktionen följer aktuell rytm och cirkulation.</span>";}
}

/* ---------- Artärkurva (invasivt BT) ---------- */
let artX=0, artLast=30;
function drawArt(dt){
  const cv=$("art");
  if(!S.artline){cv.classList.add("hidden");return;}
  cv.classList.remove("hidden");
  if(dt<=0)return;                 // pausat → artärkurvan fryser
  const g=cv.getContext("2d"),W=540,H=40,speed=90;
  const step=Math.max(1,Math.round(speed*dt));
  g.fillStyle="#141A17";g.fillRect(artX,0,step+14,H);
  const d=dbpNow(), s=S.rosc?sbpNow():d+ (S.comp?18:2);
  const map=t2=>{
    if(S.rosc){const per=60/95,ph=((t2%per)+per)%per/per;
      return ph<0.12? s-(s-d)*(ph/0.12) : d+(s-d)*Math.exp(-(ph-0.12)*6)*(ph<0.5?1:0.4);}
    if(!S.comp)return d*0.4+rnd(-1,1);
    const per=60/(S.lucas?102:110),ph=((t2%per)+per)%per/per;
    return ph<0.3? d+(s-d)*Math.sin(ph/0.3*Math.PI): d+rnd(-1,1);
  };
  const yOf=v=>H-4-(v/120)*(H-8);
  g.strokeStyle="#FF6B5E";g.lineWidth=1.8;g.beginPath();
  const y=yOf(clamp(map(S.t),0,120));
  g.moveTo(artX===0?0:artX-1,artLast);g.lineTo(artX+step,y);g.stroke();
  artLast=y; artX+=step; if(artX>=W){artX=0;artLast=y;}
  g.fillStyle="#FF6B5E";g.fillRect((artX+2)%W,0,2,H);
  g.fillStyle="#c2d2c9";g.font="9px 'IBM Plex Mono'";
  g.fillText("ART "+(S.rosc?Math.round(s)+"/"+Math.round(d):("dia "+d))+" mmHg",6,12);
}

